+export const config = (() => {
+  const modelOf = () => "briaai/Fibo-2.0-edit-turbo";
+  const plan = (s) => {
+    const flags = ["--model-path " + modelOf(s)];
+    // Single-GPU recipes: Fibo 2.0 runs in this PR without sequence or tensor parallelism.
+    if (s.hw !== "arc_b" && s.hw !== "xeon") flags.push("--num-gpus 1");
+    return {
+      flags,
+      gpus: 1,
+      topology: { tp_size: 1, ulysses_degree: 1, ring_degree: 1 },
+      env: s.hw === "xeon" ? ["SGLANG_DIFFUSION_PLATFORM_OVERRIDE=cpu"] : [],
+    };
+  };
+  const defaults = {
+    hw: "h100",
+    nodes: 1,
+    gpus_per_node: 1,
+    topology_mode: "auto",
+    tp_size: 1,
+    ulysses_degree: 1,
+    ring_degree: 1,
+  };
+  const config = {
+    modelName: "Fibo-2.0-edit-turbo",
+    supportedHardware: ["b200", "h200", "h100"],
+    hardware: [
+      { id: "b200", label: "B200", vram: "180GB", vendor: "nvidia" },
+      { id: "h200", label: "H200", vram: "141GB", vendor: "nvidia" },
+      { id: "h100", label: "H100", vram: "80GB", vendor: "nvidia" },
+    ],
+    groupHardware: false,
+    matchDims: [],
+    overlayDims: [],
+    commandBuilder: {
+      defaultSelection: defaults,
+      resource: {
+        limits: {
+          nodes: { min: 1, max: 1 },
+          gpus_per_node: { min: 1, max: 1 },
+        },
+        verifiedRecipes: ["b200", "h200", "h100"].map((hw) => {
+          const s = { ...defaults, hw };
+          const p = plan(s);
+          return {
+            ...s,
+            id: hw + "-documented",
+            gpus_per_node: p.gpus,
+            ...p.topology,
+            default: true,
+            unverified: true,
+          };
+        }),
+        autoTopology: (s) => plan(s).topology,
+        validateTopology: (s, t) => {
+          const p = plan(s);
+          const errors = [...(p.errors || [])];
+          if (!config.supportedHardware.includes(s.hw)) errors.push("Choose a listed hardware platform.");
+          if (Number(s.nodes) !== 1) errors.push("This recipe covers one node.");
+          const count = Number(s.gpus_per_node);
+          if (!Number.isInteger(count) || count < 1 || count > 1)
+            errors.push("Choose an integer GPU count within the documented limits.");
+          if (count !== p.gpus) errors.push("This recipe runs on a single GPU.");
+          if (["tp_size", "ulysses_degree", "ring_degree"].some((key) => Number(t[key]) !== p.topology[key]))
+            errors.push("This topology is not a documented recipe for the selected model and hardware.");
+          return errors;
+        },
+      },
+      resolveDeployment: (s) => {
+        const p = plan(s);
+        const topology =
+          s.topology_mode === "manual"
+            ? {
+                tp_size: Number(s.tp_size),
+                ulysses_degree: Number(s.ulysses_degree),
+                ring_degree: Number(s.ring_degree),
+              }
+            : p.topology;
+        const errors = config.commandBuilder.resource.validateTopology(s, topology);
+        const status = errors.length ? "error" : "unverified";
+        const flags = [...p.flags];
+        if (!flags.some((flag) => flag.startsWith("--port "))) flags.push("--port {{PORT}}");
+        return {
+          match: { hw: s.hw },
+          nnodes: 1,
+          verified: false,
+          flags,
+          env: p.env || [],
+          builder: {
+            topology,
+            topologySummary: "Single GPU / no sequence parallelism",
+            errors,
+            warnings: [
+              ...(p.warnings || []),
+              "Documented recipe; this exact server and request combination has not been HTTP-verified.",
+            ],
+            verification: { serve: status, request: status },
+          },
+        };
+      },
+    },
+    modelNames: { default: modelOf(defaults) },
+    placeholders: {
+      PORT: { target: "command", label: "Server port", default: "30000" },
+      CURL_HOST: { target: "curl", label: "Server host", default: "127.0.0.1" },
+      CURL_PORT: { target: "curl", label: "Request port", default: "30000" },
+      IMAGE_PATH: { target: "curl", label: "Source image", default: "photo.jpg" },
+    },
+    curl: (s) =>
+      [
+        "curl -sS http://{{CURL_HOST}}:{{CURL_PORT}}/v1/images/edits",
+        "-F image=@{{IMAGE_PATH}}",
+        "-F 'prompt=replace the jacket with a red leather one'",
+        "-F n=1",
+        "-F num_inference_steps=4",
+        "-F guidance_scale=1.0",
+        "-F response_format=b64_json",
+      ].join(" \\\n  "),
+    runModes: ["python", "curl"],
+    showPlaygroundLink: false,
+    github: { cookbookModel: modelOf(defaults) },
+  };
+  return config;
+})();

